# Process all rewrites
print(f'Batch 2: Rewriting {len(rewrites)} posts...')
for i, (pid, intros, sections, faqs, extra_tags) in enumerate(rewrites):
    full_content = BANNER
    for p in intros:
        full_content += p
    for heading, body in sections:
        full_content += f'<h2>{heading}</h2>{body}'
    
    if faqs:
        full_content += '<h2>Preguntas frecuentes</h2>'
        for q, a in faqs:
            full_content += f'<h3>{q}</h3><p>{a}</p>'
        full_content += make_faq_schema(faqs)
    
    full_content += AFF
    
    tags = [TAG_CUIDADOS]
    if TAG_AVES_NATIVAS:
        tags.append(TAG_AVES_NATIVAS)
    for et in extra_tags:
        tid = tag_id(et)
        if tid:
            tags.append(tid)
    tags = list(set(t for t in tags if t))
    
    if update_post(pid, full_content, tags):
        print(f'  OK {pid} ({i+1}/{len(rewrites)})')
    else:
        print(f'  FAIL {pid} ({i+1}/{len(rewrites)})')
    if i % 3 == 0:
        time.sleep(1)

print('Batch 2 done')
